import{_ as o,a0 as l,w as p,s as r,I as t,x as e,a1 as a,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"我在源码控制中维护点文件的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"我在源码控制中维护点文件的技巧 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我在源码控制中维护点文件的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我在源码控制中维护点文件的技巧 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220208 My tips for maintaining dotfiles in source control","title":"我在源码控制中维护点文件的技巧","tag":"202202","desc":""},"relativePath":"202202/20220208 My tips for maintaining dotfiles in source control.md","filePath":"[post].md"}'),u={name:"202202/20220208 My tips for maintaining dotfiles in source control.md"};function f(g,s,m,h,c,b){const n=l("Link");return p(),r("div",null,[s[18]||(s[18]=t("h1",{id:"我在源码控制中维护点文件的技巧",tabindex:"-1"},[e("我在源码控制中维护点文件的技巧 "),t("a",{class:"header-anchor",href:"#我在源码控制中维护点文件的技巧","aria-label":"Permalink to “我在源码控制中维护点文件的技巧”"},"​")],-1)),s[19]||(s[19]=t("blockquote",null,[t("p",null,"当你把环境保持在源码控制中，开发虚拟机和容器就成了一个解决方案，而不是一个问题。")],-1)),s[20]||(s[20]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/18/145014pc7lmh5ts15mm0tm.jpg",alt:""})],-1)),s[21]||(s[21]=t("p",null,[e("你是否曾经开始使用一台新的电脑，不管是出于自愿还是因为旧的电脑让你的魔法烟消云散，并且对花了多长时间才把所有东西都 "),t("em",null,"弄好"),e(" 而感到沮丧？更糟糕的是，有没有花了一些时间重新配置你的 shell 提示符，然后意识到你更喜欢以前的样子？")],-1)),t("p",null,[s[1]||(s[1]=e("对我来说，当我决定要在 ",-1)),a(n,{href:"https://opensource.com/tags/containers"},{default:i(()=>[...s[0]||(s[0]=[e("容器",-1)])]),_:1}),s[2]||(s[2]=e(" 中进行开发时，这个问题就变得很严重了。容器是非持久的。开发工具很容易解决：一个带有工具的容器镜像就可以工作。源码很容易解决：源码控制维护它，开发是在分支上。但是，如果每次我创建一个容器，我都需要仔细地配置它，这就太痛苦了。",-1))]),s[22]||(s[22]=d(`<h3 id="主目录的版本控制" tabindex="-1">主目录的版本控制 <a class="header-anchor" href="#主目录的版本控制" aria-label="Permalink to “主目录的版本控制”">​</a></h3><p>将配置文件保存在版本控制中一直是一个有吸引力的选择。但是天真地这么做是令人担忧的。不可能直接对 <code>~</code> 进行版本控制。</p><p>首先，太多的程序认为把秘密放在那里是安全的。此外，它也是 <code>~/Downloads</code> 和 <code>~/Pictures</code> 等文件夹的位置，这些文件夹可能不应该被版本化。</p><p>小心翼翼地在主目录下保留一个 <code>.gitignore</code> 文件来管理 <code>include</code> 和 <code>exclude</code> 列表是有风险的。在某些时候，其中一个路径会出错，花费了几个小时的配置会丢失，大文件会出现在 Git 历史记录中，或者最糟糕的是，秘密和密码会被泄露。当这一策略失败时，它就成了灾难性的失败。</p><p>手动维护大量的符号链接也是行不通的。版本控制的全部原因是为了避免手动维护配置。</p><h3 id="写一个安装脚本" tabindex="-1">写一个安装脚本 <a class="header-anchor" href="#写一个安装脚本" aria-label="Permalink to “写一个安装脚本”">​</a></h3><p>这暗示了在源码控制中维护点文件的第一条线索：写一个安装脚本。</p><p>就像所有好的安装脚本一样，让它 <em>幂等</em>：运行两次不会两次增加配置。</p><p>像所有好的安装脚本一样，让它 <em>只做最少的事情</em>：使用其他的技巧来指向你的源码控制中的配置文件。</p><h3 id="config-目录" tabindex="-1">~/.config 目录 <a class="header-anchor" href="#config-目录" aria-label="Permalink to “~/.config 目录”">​</a></h3><p>现代 Linux 程序在直接在主目录中寻找配置之前，会先在 <code>~/.config</code> 中寻找。最重要的例子是 <code>git</code>，它在 <code>~/.config/git</code> 中寻找。</p><p>这意味着安装脚本可以将 <code>~/.config</code> 符号链接到主目录中源码控制的管理目录中的一个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span>DOTFILES=&quot;$(dirname $(realpath $0))&quot;</span></span>
<span class="line"><span>[ -L ~/.config ] || ln -s $DOTFILES/config ~/.config</span></span></code></pre></div><p>此脚本寻找它的位置，然后将 <code>~/.config</code> 链接到它被签出的地方。这意味着几乎没有关于它需要位于主目录中的位置的假设。</p><h3 id="获取文件" tabindex="-1">获取文件 <a class="header-anchor" href="#获取文件" aria-label="Permalink to “获取文件”">​</a></h3><p>大多数 shells 仍然直接在主目录下寻找文件。为了解决这个问题，你要增加一层指示。从 <code>$DOTFILES</code> 中获取文件意味着在修改 shell 配置时不需要重新运行安装程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span>DOTFILES=&quot;$(dirname $(realpath $0))&quot;</span></span>
<span class="line"><span>grep -q &#39;SETTING UP BASH&#39; ~/.bashrc || \\</span></span>
<span class="line"><span>  echo &quot;source $DOTFILES/starship.bash # SETTING UP BASH&quot; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>再次注意，这个脚本很仔细地做了幂等：如果这一行已经在那里了，它就不会再添加。它还考虑到了你在 <code>.bashrc</code> 上已经做的任何编辑，虽然这不是一个好主意，但也没有必要惩罚它。</p><h3 id="反复测试" tabindex="-1">反复测试 <a class="header-anchor" href="#反复测试" aria-label="Permalink to “反复测试”">​</a></h3><p>当你把环境保持在源码控制中时，开发虚拟机和容器就成了一个解决方案，而不是一个问题。试着做一个实验。建立一个新的开发环境，克隆你的点文件，安装，并看看有什么问题。</p><p>不要只做一次。至少每周做一次。这将使你更快地完成工作，同时也会告诉你什么是不可行的。暴露问题，修复它们，然后重复。</p><hr>`,22)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/22/2/dotfiles-source-control"},{default:i(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/22/2/dotfiles-source-control",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[5]||(s[5]=[e("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const C=o(u,[["render",f]]);export{x as __pageData,C as default};
